mapper.update:
UPDATE activity
SET state = #{afterState}, update_time = now()
WHERE activity_id = #{activityId}
  AND state = #{beforeState}

mapper.select:
SELECT count(*) FROM activity


        AND activity_id = #{activityId}


        AND activity_name = #{activityName}

SELECT id, activity_id, activity_name, activity_desc, begin_date_time, end_date_time,
take_count, draw_config_id, state, creator, create_time, update_time
FROM activity


        AND activity_id = #{activityId}


        AND activity_name = #{activityName}


ORDER BY id DESC
LIMIT #{pageBegin}, #{pageEnd}
